#!/usr/bin/env bash
# Shared helpers for the posting toolkit (post/*.sh).
#
# Every script sources this file, so the footer contract lives in one place:
# the identity tag, the attribution signature and the metadata marker are
# appended here, never typed by the agent. A hand-rolled artifact can print
# the same block with artifact-footer.sh.

set -euo pipefail

# gh api takes endpoints relative to the API root (no leading slash): Git Bash
# rewrites a leading-slash argument into a Windows path, which is exactly what
# a local operator would hit; the Linux runners accept both forms.

REVIEW_TAG='<!-- mirrobot:review -->'
COMPLIANCE_TAG='<!-- mirrobot:compliance -->'
REVIEW_SIGNATURE='_This review was generated by an AI assistant._'
COMPLIANCE_SIGNATURE='_Compliance verification by AI agent • Re-run with `/mirrobot-check`_'
COMMENT_SIGNATURE='_This response was generated by an AI assistant._'

die() { printf 'error: %s\n' "$*" >&2; exit 1; }
note() { printf '%s\n' "$*" >&2; }

repo_or_die() {
  local r="${GH_REPO:-${GITHUB_REPOSITORY:-}}"
  [ -n "$r" ] || die "no repository: pass --repo or set GH_REPO"
  printf '%s' "$r"
}

num_or_die() {
  [ -n "${1:-}" ] || die "$2 is required (pass it or set PR_NUMBER/THREAD_NUMBER)"
  case "$1" in *[!0-9]*) die "$2 must be numeric: $1" ;; esac
  printf '%s' "$1"
}

pr_default() { printf '%s' "${PR_NUMBER:-${THREAD_NUMBER:-}}"; }

require_file() {
  [ -f "$1" ] || die "file not found: $1"
  [ -s "$1" ] || die "file is empty: $1"
}

trim_blank_tail() { # $1 src, $2 out
  awk '{ l[NR] = $0 } END { n = NR; while (n > 0 && l[n] ~ /^[[:space:]]*$/) n--; for (i = 1; i <= n; i++) print l[i] }' "$1" > "$2"
}

has_literal() { grep -qF -- "$2" "$1"; }

sha_resolve() { # $1 explicit (may be empty), $2 allow_missing (0/1) -> prints full SHA
  local sha="${1:-}"
  if [ -z "$sha" ] && [ -f /tmp/head_sha.txt ]; then
    sha=$(tr -d '[:space:]' < /tmp/head_sha.txt)
  fi
  if [ -z "$sha" ]; then sha=$(git rev-parse HEAD 2>/dev/null || true); fi
  [ -n "$sha" ] || die "no commit SHA: pass --sha, or provide /tmp/head_sha.txt"
  case "$sha" in *[!0-9a-fA-F]*) die "not a hex SHA: $sha" ;; esac
  [ "${#sha}" -ge 7 ] && [ "${#sha}" -le 40 ] || die "SHA length ${#sha} is not 7..40: $sha"
  if git rev-parse --git-dir >/dev/null 2>&1; then
    if git cat-file -e "${sha}^{commit}" 2>/dev/null; then
      sha=$(git rev-parse "${sha}^{commit}")
    elif [ "$2" != 1 ]; then
      die "commit $sha is not in this repository (fetch it, or pass --allow-missing-sha if the API knows it)"
    else
      note "warning: commit $sha not found locally; proceeding on request"
    fi
  fi
  printf '%s' "$sha"
}

find_diff() { # $1 explicit diff path (may be empty) -> prints a path, or nothing
  local explicit="${1:-}" pr cand
  if [ -n "$explicit" ]; then
    [ -f "$explicit" ] || die "diff file not found: $explicit"
    printf '%s' "$explicit"
    return 0
  fi
  if [ -n "${DIFF_FILE_PATH:-}" ] && [ -f "$DIFF_FILE_PATH" ]; then
    printf '%s' "$DIFF_FILE_PATH"
    return 0
  fi
  pr=$(pr_default)
  if [ -n "$pr" ]; then
    for cand in "/tmp/kit/$pr/full_diff.patch" "/tmp/kit/$pr/incremental_diff.patch"; do
      if [ -f "$cand" ]; then printf '%s' "$cand"; return 0; fi
    done
  fi
  if git rev-parse --git-dir >/dev/null 2>&1; then
    local base="${BASE_BRANCH:-}" mb="" b out
    if [ -n "$base" ] && git rev-parse --verify "origin/$base" >/dev/null 2>&1; then
      mb=$(git merge-base "origin/$base" HEAD 2>/dev/null || true)
    else
      for b in main master; do
        if git rev-parse --verify "origin/$b" >/dev/null 2>&1; then
          mb=$(git merge-base "origin/$b" HEAD 2>/dev/null || true)
          [ -n "$mb" ] && break
        fi
      done
    fi
    if [ -n "$mb" ]; then
      out=$(mktemp)
      git diff --full-index "$mb"..HEAD > "$out" 2>/dev/null || true
      if [ -s "$out" ]; then printf '%s' "$out"; return 0; fi
      rm -f "$out"
    fi
  fi
  printf ''
}

validate_comment() { # $1 diff $2 path $3 line $4 side $5 start_line $6 filelevel(0/1)
  local diff=$1 path=$2 line=${3:-0} side=${4:-RIGHT} start=${5:-0} filelevel=${6:-0}
  awk -v want_path="$path" -v want_line="$line" -v want_side="$side" \
      -v want_start="$start" -v filelevel="$filelevel" '
    function emit(msg) { print msg > "/dev/stderr" }
    BEGIN { nr = 0 }
    /^diff --git / {
      # Register the new-side path here too: binary and pure-rename diffs have
      # no ---/+++ lines, and a file-level comment must still find the path.
      s = $0; sub(/^diff --git /, "", s)
      n = split(s, parts, " b/")
      if (n >= 2) { cur = parts[n]; seen[cur] = 1; new = parts[n]; old = "" }
      next
    }
    /^--- / {
      p = $0; sub(/^--- /, "", p); sub(/^a\//, "", p); sub(/\r$/, "", p)
      old = (p == "/dev/null") ? "" : p
      next
    }
    /^\+\+\+ / {
      p = $0; sub(/^\+\+\+ /, "", p); sub(/^b\//, "", p); sub(/\r$/, "", p)
      new = (p == "/dev/null") ? "" : p
      cur = (new != "") ? new : old
      if (cur != "") seen[cur] = 1
      if (old != "") seen[old] = 1
      next
    }
    /^@@ / {
      if (cur == "") next
      os = $2; sub(/^-/, "", os); split(os, oa, ",")
      oc = (oa[2] == "") ? 1 : oa[2] + 0; os = oa[1] + 0
      ns = $3; sub(/^\+/, "", ns); split(ns, na, ",")
      nc = (na[2] == "") ? 1 : na[2] + 0; ns = na[1] + 0
      if (ns > 0 && nc > 0) { k = ++nr; rp[k] = cur; rs[k] = ns; re[k] = ns + nc - 1; sd[k] = "RIGHT" }
      if (os > 0 && oc > 0) { k = ++nr; rp[k] = cur; rs[k] = os; re[k] = os + oc - 1; sd[k] = "LEFT" }
      next
    }
    END {
      if (!(want_path in seen)) {
        emit("path is not in the PR diff: " want_path)
        exit 1
      }
      if (filelevel == 1) exit 0
      ok = 0
      for (i = 1; i <= nr; i++) {
        if (rp[i] != want_path || sd[i] != want_side) continue
        if (want_line >= rs[i] && want_line <= re[i]) {
          if (want_start > 0) {
            if (want_start >= rs[i] && want_start < want_line) ok = 1
          } else ok = 1
        }
      }
      if (ok == 1) exit 0
      below = 0; above = 0
      for (i = 1; i <= nr; i++) {
        if (rp[i] != want_path || sd[i] != want_side) continue
        if (re[i] < want_line && re[i] > below) below = re[i]
        if (rs[i] > want_line && (above == 0 || rs[i] < above)) above = rs[i]
      }
      msg = "line " want_line " is not commentable on the " want_side " side of " want_path
      if (below > 0) msg = msg "; nearest below: " below
      if (above > 0) msg = msg "; nearest above: " above
      if (below == 0 && above == 0) msg = msg "; no commentable " want_side " lines in this file (binary, deleted, or pure rename)"
      emit(msg "; comment on a line the diff shows, or use --file-level")
      exit 1
    }
  ' "$diff"
}

validate_comment_json() { # $1 comments json file -> 0 ok, 1 problems printed
  local file=$1 n i path body line start side ftype rc=0 diff=""
  n=$(jq 'length' "$file")
  diff=$(find_diff "${DIFF_PATH:-}")
  i=0
  while [ "$i" -lt "$n" ]; do
    path=$(jq -r ".[$i].path // empty" "$file")
    body=$(jq -r ".[$i].body // empty" "$file")
    line=$(jq -r ".[$i].line // empty" "$file")
    start=$(jq -r ".[$i].start_line // empty" "$file")
    side=$(jq -r ".[$i].side // \"RIGHT\"" "$file")
    ftype=$(jq -r ".[$i].subject_type // \"line\"" "$file")
    if [ -z "$path" ] || [ -z "$body" ]; then
      note "comment $i: path and body are required"
      rc=1; i=$((i + 1)); continue
    fi
    if [ "$ftype" != "file" ] && [ -z "$line" ]; then
      note "comment $i: line is required (or set subject_type: file)"
      rc=1; i=$((i + 1)); continue
    fi
    if [ -z "$diff" ]; then
      note "comment $i: no diff available, skipping line validation"
    elif [ "$ftype" = "file" ]; then
      if ! validate_comment "$diff" "$path" 0 "$side" 0 1; then
        note "comment $i: $path"
        rc=1
      fi
    else
      if ! validate_comment "$diff" "$path" "$line" "$side" "${start:-0}" 0; then
        note "comment $i: $path:$line"
        rc=1
      fi
    fi
    i=$((i + 1))
  done
  return "$rc"
}

prepare_review_body() { # $1 src body, $2 out, $3 sha
  local src=$1 out=$2 sha=$3 declared
  declared=$(grep -oE 'last_reviewed_sha:[a-f0-9]{7,40}' "$src" | tail -1 | cut -d: -f2 || true)
  if [ -n "$declared" ] && [ "$declared" != "$sha" ]; then
    die "body declares last_reviewed_sha:$declared but the resolved SHA is $sha; fix the marker, or pass --sha $declared"
  fi
  trim_blank_tail "$src" "$out"
  printf '\n\n' >> "$out"
  if ! has_literal "$src" "$REVIEW_TAG"; then printf '%s\n' "$REVIEW_TAG" >> "$out"; fi
  if ! has_literal "$src" "$REVIEW_SIGNATURE"; then printf '%s\n' "$REVIEW_SIGNATURE" >> "$out"; fi
  if ! has_literal "$src" "<!-- last_reviewed_sha:${sha} -->"; then
    printf '<!-- last_reviewed_sha:%s -->\n' "$sha" >> "$out"
  fi
}

prepare_compliance_body() { # $1 src body, $2 out, $3 pr, $4 sha
  local src=$1 out=$2 pr=$3 sha=$4 declared
  declared=$(grep -oE 'compliance-check-id: [0-9]+-[a-f0-9]{7,40}' "$src" | tail -1 | sed 's/compliance-check-id: //' || true)
  if [ -n "$declared" ] && [ "$declared" != "${pr}-${sha}" ]; then
    die "body declares compliance-check-id:${declared} but this run is ${pr}-${sha}; fix the marker, or pass the matching --pr/--sha"
  fi
  trim_blank_tail "$src" "$out"
  printf '\n\n' >> "$out"
  if ! has_literal "$src" "$COMPLIANCE_TAG"; then printf '%s\n' "$COMPLIANCE_TAG" >> "$out"; fi
  if ! has_literal "$src" "$COMPLIANCE_SIGNATURE"; then printf '%s\n' "$COMPLIANCE_SIGNATURE" >> "$out"; fi
  if ! has_literal "$src" "<!-- compliance-check-id: ${pr}-${sha} -->"; then
    printf '<!-- compliance-check-id: %s-%s -->\n' "$pr" "$sha" >> "$out"
  fi
}

usage_common() {
  printf 'Run --help for usage.\n' >&2
}
